"""Preserve the exact root-qualified launcher as an add-on to the base runtime.

Run only after all timing finishes. This hashes the immutable base archive and
creates a small separate archive; it never rewrites that base archive. No JVM,
compiler, Git, network, or benchmark process runs. Output is a NEW directory.
"""

from __future__ import annotations

import argparse
import gzip
import hashlib
import io
import json
import os
from pathlib import Path
import runpy
import stat
import tarfile
import tempfile


EVIDENCE = "result-coordinate-evidence"
PREFIX = "rdf4j/"
ARCHIVE_NAME = "rdf4j-root-qualified-runtime-addon.tar.gz"
MANIFEST_NAME = "root-qualified-runtime-manifest.json"
BASE_ARCHIVE_NAME = "rdf4j-coordinate-runtimes.tar.gz"
BASE_ARCHIVE_SHA256 = "645e53e52b1e515c0a95bf3c8224a06285c5baa3aba92d9cc30cafa99323a422"


def readme() -> bytes:
    return """# Root-qualified runtime add-on

This small archive extends the separately preserved base runtime archive. The
base archive remains byte-identical (SHA-256
645e53e52b1e515c0a95bf3c8224a06285c5baa3aba92d9cc30cafa99323a422).
Extract the base archive, then this add-on, into the same parent directory.
Both begin with rdf4j/. Files do not overlap; shared parent directories do.

The actual measured classpath contained the original 126 frozen-current entries
in unchanged order, followed LAST by one directory with the unique launcher
class. The exact measured class directory is preserved; it has not been replaced
by a newly generated JAR. The launcher delegates the unchanged harness and reads
root-host counters only after the original main completes. It does not add any
per-query instrumentation to the measured loop.

Original protocol, classpath strings, manifests, launcher source/class, and all
driver bytes remain intact. Original absolute paths document the measurement
host. They should not be edited to reproduce the experiment elsewhere. Instead:

    python3 rdf4j/result-coordinate-evidence/rebase-root-qualified-experiment.py \\
      --java /path/to/compatible/bin/java --output /new/reproduction-plan

The helper validates the 126 base artifacts, source identity, and exact launcher
artifact, then writes a NEW 127-entry classpath, rebased reference manifest,
derivative protocol, and explicit command in a new directory. It never runs
Java. The derivative changes host paths and reproduction provenance; the fixed
four modes, four balanced rounds, five warmups, five measurements, default input,
1 GiB heap/G1/AUTO selection, and strict root-host failure policy remain intact.
The original prespecified protocol is also preserved and is not relabelled as a
protocol for the future machine. A compatible local JVM/platform is necessary;
the measured JVM was Eclipse Adoptium 25.0.5+8-LTS. Reproduction does not promise
identical timing on another host. The original driver uses POSIX process groups.

The helper prints the exact command without executing it. When deliberately
running that command, arrange quiet serial timing. The unchanged driver checks
all artifact hashes before/after the new run and rejects nonzero generic-root
hosting, incomplete/invalid data, or changed artifacts without replacing forks.

No stores, JDK, Maven cache, or credentials are included. Original evidence and
the recorded experiment's raw query results are in the separate evidence
archive. This add-on is for preserving execution bytes and reproduction inputs.
root-qualified-runtime-manifest.json lists its members and hashes; external
runtime-addon-verification.json and SHA256SUMS record the generated
manifest/archive bytes for delivery verification. Archive members are read
back and hashed before atomic no-overwrite publication.
""".encode("utf-8")


def main() -> None:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--repo", type=Path, default=Path(__file__).resolve().parents[1])
    parser.add_argument("--base-delivery", type=Path, required=True,
                        help="Previously verified base-runtime delivery directory")
    parser.add_argument("--output", type=Path, required=True, help="New directory outside the checkout")
    args = parser.parse_args()
    repo = args.repo.resolve(strict=True)
    evidence = repo / EVIDENCE
    base = args.base_delivery.resolve(strict=True)
    output = args.output.parent.resolve(strict=True) / args.output.name
    api = runpy.run_path(str(evidence / "rebase-coordinate-classpath.py"))
    base_bundle = runpy.run_path(str(evidence / "bundle-coordinate-runtimes.py"))
    addon = runpy.run_path(str(evidence / "rebase-root-qualified-experiment.py"))
    require, digest_file = api["require"], api["file_digest"]
    canonical_json = base_bundle["canonical_json"]
    require(not os.path.lexists(output), f"Refusing to replace output: {output}")
    require(not output.is_relative_to(repo) and not output.is_relative_to(base),
            "Use a separate staging directory outside checkout and base delivery")
    summary = json.loads((evidence / "root-qualified-transport-comparison/summary.json").read_bytes())
    require(summary["rootQualification"]["status"] == "complete"
            and summary["completeForks"] == 16 and summary["excludedForks"] == 0,
            "The complete root-qualified confirmation must finish before packaging")
    base_archive = base / BASE_ARCHIVE_NAME
    base_stat = base_archive.stat()
    require(digest_file(base_archive) == BASE_ARCHIVE_SHA256, "Immutable base archive hash differs")
    base_verification = json.loads((base / "runtime-verification.json").read_bytes())
    require(base_verification["archive"]["sha256"] == BASE_ARCHIVE_SHA256
            and base_verification["archive"]["bytes"] == base_stat.st_size,
            "Base verification/archive identity differs")
    base_manifest_path = base / "runtime-bundle-manifest.json"
    require(digest_file(base_manifest_path) == base_verification["manifestSha256"],
            "Base manifest hash differs")
    base_manifest = json.loads(base_manifest_path.read_bytes())
    inputs = addon["validate_inputs"](repo, api)
    protocol = inputs["protocol"]
    require(base_manifest["runtimes"][0]["source"] == protocol["source"],
            "Base frozen source differs from the confirmation")
    reference_name = PREFIX + protocol["frozenClasspathManifest"]
    require(base_manifest["members"][reference_name]["sha256"]
            == protocol["frozenClasspathManifestSha256"],
            "Base archive does not preserve the original reference manifest")
    run_root = evidence / "root-qualified-transport-comparison"
    for copied, original in (("protocol.json", repo / addon["PROTOCOL"]),
                             ("driver.py", repo / protocol["driver"]),
                             ("launcher.java", repo / protocol["launcherSource"])):
        require((run_root / copied).read_bytes() == original.read_bytes(),
                f"Recorded experiment input copy differs: {copied}")
    records: dict[str, dict] = {}
    payloads: dict[str, Path | bytes] = {}

    def add_directory(name: str) -> None:
        existing = base_manifest["members"].get(name)
        require(existing is None or existing["kind"] == "directory", f"Base file collision: {name}")
        records.setdefault(name, {"kind": "directory", "mode": 0o755, "size": 0})

    def add_parents(name: str) -> None:
        parts = name.split("/")
        for index in range(1, len(parts)):
            add_directory("/".join(parts[:index]))

    def add_file(path: Path) -> None:
        name = PREFIX + path.relative_to(repo).as_posix()
        require(name not in records and name not in base_manifest["members"],
                f"Duplicate member or base-file overlap: {name}")
        before = path.lstat()
        require(stat.S_ISREG(before.st_mode), f"Expected regular archive input: {path}")
        add_parents(name)
        records[name] = {"kind": "file", "mode": stat.S_IMODE(before.st_mode) & 0o777,
                         "size": before.st_size, "sha256": digest_file(path)}
        payloads[name] = path

    def add_bytes(name: str, content: bytes) -> None:
        require(name not in records and name not in base_manifest["members"],
                f"Duplicate generated member or base-file overlap: {name}")
        add_parents(name)
        records[name] = {"kind": "file", "mode": 0o644, "size": len(content),
                         "sha256": hashlib.sha256(content).hexdigest()}
        payloads[name] = content

    relative_files = [addon["PROTOCOL"], protocol["driver"], protocol["originalDriver"],
                      protocol["launcherSource"], protocol["classpathFile"], addon["MEASURED_MANIFEST"],
                      f"{EVIDENCE}/freeze-experiment-classpath.py"]
    relative_files += [f"{EVIDENCE}/root-qualified-launcher/{name}" for name in
                       ("README.md", "build-command.json", "build.log", "overlay-manifest.json")]
    relative_files += [f"{EVIDENCE}/root-qualified-transport-comparison/{name}" for name in
                       ("protocol.json", "driver.py", "launcher.java", "configuration.json")]
    relative_files += [f"{EVIDENCE}/{name}" for name in addon["SCRIPT_NAMES"]]
    for relative in relative_files:
        add_file(repo / relative)
    for path in inputs["overlayDirectories"]:
        name = PREFIX + path.relative_to(repo).as_posix()
        add_parents(name)
        add_directory(name)
    for path in inputs["overlayFiles"]:
        add_file(path)
    add_bytes(PREFIX + EVIDENCE + "/ROOT-QUALIFIED-RUNTIME.md", readme())
    manifest = canonical_json({
        "format": 1, "source": protocol["source"],
        "scope": "Separate exact launcher-directory add-on; original base archive is immutable",
        "baseArchive": base_verification["archive"], "originalBaseEntries": 126,
        "actualClasspathEntries": 127,
        "appendedEntry": {"position": 127, "path": PREFIX + addon["CLASS_DIRECTORY"],
                          "kind": "tree", "files": 1, "sha256": inputs["overlayHash"]},
        "protocolSha256": hashlib.sha256(inputs["protocolBytes"]).hexdigest(),
        "directoryHashAlgorithm": "SHA256(pathlib-sorted POSIX relative file name + NUL + raw file SHA256)",
        "members": {name: records[name] for name in sorted(records)},
        "note": "Member map excludes this generated manifest itself. No original metadata is rewritten.",
    })
    add_bytes(PREFIX + EVIDENCE + "/" + MANIFEST_NAME, manifest)
    temporary = Path(tempfile.mkdtemp(prefix=".root-qualified-runtime-", dir=output.parent))
    try:
        archive_path = temporary / ARCHIVE_NAME
        with archive_path.open("xb") as raw:
            with gzip.GzipFile(filename="", mode="wb", fileobj=raw, mtime=0, compresslevel=6) as compressed:
                with tarfile.open(mode="w|", fileobj=compressed, format=tarfile.PAX_FORMAT) as archive:
                    for name in sorted(records):
                        record = records[name]
                        member = tarfile.TarInfo(name)
                        member.mode = record["mode"]
                        member.mtime = member.uid = member.gid = 0
                        member.uname = member.gname = ""
                        if record["kind"] == "directory":
                            member.type = tarfile.DIRTYPE
                            archive.addfile(member)
                        else:
                            member.size = record["size"]
                            payload = payloads[name]
                            if isinstance(payload, bytes):
                                archive.addfile(member, io.BytesIO(payload))
                            else:
                                with payload.open("rb") as stream:
                                    archive.addfile(member, stream)
            raw.flush()
            os.fsync(raw.fileno())
        seen, archived_hashes = set(), {}
        with tarfile.open(archive_path, "r|gz") as archive:
            for member in archive:
                name = member.name.rstrip("/") if member.isdir() else member.name
                require(name in records and name not in seen, f"Unexpected/duplicate archived member: {name}")
                seen.add(name)
                expected = records[name]
                require(member.mode == expected["mode"] and member.uid == member.gid == member.mtime == 0
                        and not member.uname and not member.gname, f"Archive metadata differs: {name}")
                if expected["kind"] == "directory":
                    require(member.isdir(), f"Expected archived directory: {name}")
                    continue
                require(member.isfile() and member.size == expected["size"], f"Archive type/size differs: {name}")
                stream = archive.extractfile(member)
                require(stream is not None, f"Unreadable archived file: {name}")
                with stream:
                    archived_hashes[name] = hashlib.sha256(stream.read()).hexdigest()
                require(archived_hashes[name] == expected["sha256"], f"Archived content differs: {name}")
        require(seen == set(records), "Archive is missing declared members")
        class_name = PREFIX + addon["CLASS_DIRECTORY"] + "/" + addon["CLASS_FILE"]
        require(api["tree_digest"]({addon["CLASS_FILE"]: archived_hashes[class_name]}) == inputs["overlayHash"],
                "Archived launcher tree digest differs")
        after = base_archive.stat()
        require((base_stat.st_dev, base_stat.st_ino, base_stat.st_size, base_stat.st_mtime_ns, base_stat.st_ctime_ns)
                == (after.st_dev, after.st_ino, after.st_size, after.st_mtime_ns, after.st_ctime_ns),
                "Base archive changed during add-on packaging")
        (temporary / MANIFEST_NAME).write_bytes(manifest)
        verification = canonical_json({
            "verified": True, "baseArchive": base_verification["archive"],
            "baseArchiveUnmodified": True, "originalBaseEntries": 126, "actualClasspathEntries": 127,
            "overlayPosition": "last", "overlayDirectorySha256": inputs["overlayHash"],
            "membersReadBack": len(seen), "filesHashedAfterReadBack": len(archived_hashes),
            "archive": {"name": ARCHIVE_NAME, "bytes": archive_path.stat().st_size,
                        "sha256": digest_file(archive_path)},
            "manifestSha256": hashlib.sha256(manifest).hexdigest(),
            "originalMetadataPreserved": True,
        })
        (temporary / "runtime-addon-verification.json").write_bytes(verification)
        (temporary / "SHA256SUMS").write_text("".join(f"{digest_file(temporary / name)}  {name}\n"
                for name in (ARCHIVE_NAME, MANIFEST_NAME, "runtime-addon-verification.json")), encoding="utf-8")
        base_bundle["publish_directory"](temporary, output)
        print(f"Published verified runtime add-on: {output / ARCHIVE_NAME}")
    except BaseException:
        print(f"Unpublished staging retained for inspection: {temporary}")
        raise


if __name__ == "__main__":
    main()
